fn projection_bound(
    bounds: &mut [ParameterBound],
    parameter: &str,
    kind: &str,
    value: ProjectionValue,
) {
    if let Some(b) = bounds.iter_mut().find(|b| b.parameter == parameter) {
        match kind {
            "min" => {
                if b.min.as_ref().map_or(true, |v| *v < value) {
                    b.min = Some(value)
                }
            }
            "max" => {
                if b.max.as_ref().map_or(true, |v| *v > value) {
                    b.max = Some(value)
                }
            }
            "exact" => b.exact = Some(value),
            _ => {}
        }
    }
}

